#include <print>
#include <queue>
#include <vector>

int main() {
    const char* maze[3] = {"S.#.", ".#..", "...G"};
    int R = 3, C = 4;
    std::vector<std::vector<int>> dist(R, std::vector<int>(C, -1));
    std::queue<std::pair<int, int>> q;
    q.push({0, 0}); dist[0][0] = 0;
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [dr, dc] : {std::pair{0,1}, std::pair{1,0}, std::pair{0,-1}, std::pair{-1,0}}) {
            int nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= R || nc < 0 || nc >= C || maze[nr][nc] == '#' || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            q.push({nr, nc});
        }
    }
    for (int r = 0; r < R; ++r) {
        for (int c = 0; c < C; ++c) std::print("{:3}", dist[r][c]);
        std::println("");
    }
    const char* wall[3] = {"S.#.", "##..", "...G"};
    std::println("S 到 G 最少 {}", dist[2][3]);   // 变成 -1，说明这格压根没被淹到
    return 0;
}

